package com.desktodo.app;
import org.json.*;import java.time.*;import java.time.temporal.*;import java.time.format.DateTimeFormatter;import java.util.*;
/** Deterministic card values. Dates/statistics never depend on model-generated claims. */
final class ScreenData {
 static final ZoneId ZONE=ZoneId.of("Asia/Shanghai");
 static final String[] CARD_KEYS={"plant","week","countdown","outdoor","status","note","nextEvent","commute","habits","inspiration","plugin"};
 static final String[] CARD_NAMES={"生长小盆栽","本周进度","重要日倒计时","出门提示","办公状态","桌面小纸条","下一场日程","通勤建议","习惯打卡","每日灵感","数据插件"};
 static String label(String key){for(int i=0;i<CARD_KEYS.length;i++)if(CARD_KEYS[i].equals(key))return CARD_NAMES[i];return "桌面小纸条";}
 static JSONArray ledger(JSONArray previous,JSONArray history,JSONArray active,Instant now)throws Exception{Map<String,JSONObject> records=new HashMap<>();for(JSONArray source:new JSONArray[]{previous,history})for(int i=0;i<source.length();i++){JSONObject item=source.optJSONObject(i);if(item==null||!item.optString("recordType").equals("completed"))continue;try{Instant at=Instant.parse(item.getString("completedAt"));if(at.isBefore(now.minusSeconds(56L*86400))||at.isAfter(now))continue;String id=item.getString("id");JSONObject old=records.get(id);if(old==null||Instant.parse(old.getString("completedAt")).isBefore(at))records.put(id,new JSONObject().put("id",id).put("completedAt",at.toString()).put("recordType","completed"));}catch(Exception ignored){}}for(int i=0;i<active.length();i++)records.remove(active.optJSONObject(i).optString("id"));List<JSONObject> sorted=new ArrayList<>(records.values());sorted.sort((a,b)->b.optString("completedAt").compareTo(a.optString("completedAt")));JSONArray out=new JSONArray();for(int i=0;i<Math.min(4096,sorted.size());i++)out.put(sorted.get(i));return out;}
 static int weekCount(JSONArray history,Instant now){LocalDate monday=now.atZone(ZONE).toLocalDate().with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));Instant start=monday.atStartOfDay(ZONE).toInstant(),end=monday.plusWeeks(1).atStartOfDay(ZONE).toInstant();Set<String> counted=new HashSet<>();for(int i=0;i<history.length();i++){JSONObject t=history.optJSONObject(i);if(t==null||!t.optString("recordType").equals("completed"))continue;try{Instant done=Instant.parse(t.getString("completedAt"));if(!done.isBefore(start)&&done.isBefore(end)&&!done.isAfter(now))counted.add(t.getString("id"));}catch(Exception ignored){}}return counted.size();}
 static int plantStage(int completed,int goal){return Math.min(5,Math.max(0,completed)*5/Math.max(1,goal));}
 static JSONObject renderConfig(JSONObject cfg,JSONArray history,Instant now)throws Exception{return DeskModel.copy(cfg).put("_weekCount",weekCount(history,now));}
 static JSONObject datesConfig(JSONObject cfg,String title,LocalDate date)throws Exception{if(title.trim().isEmpty()||title.trim().length()>30)throw new Exception("名称1至30字");JSONArray dates=cfg.optJSONArray("dates")==null?new JSONArray():DeskModel.copy(cfg.getJSONArray("dates"));if(dates.length()>=12)throw new Exception("最多十二个重要日期");dates.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("title",title.trim()).put("date",date.toString()));return DeskModel.copy(cfg).put("dates",dates);}
 static String countdown(JSONObject cfg,Instant now){if(!cfg.has("dates")&&cfg.has("countdownText"))return cfg.optString("countdownText");LocalDate today=now.atZone(ZONE).toLocalDate();JSONArray dates=cfg.optJSONArray("dates");JSONObject chosen=null;LocalDate chosenDate=null;if(dates!=null)for(int i=0;i<dates.length();i++){JSONObject item=dates.optJSONObject(i);try{LocalDate day=LocalDate.parse(item.getString("date"));if(chosenDate==null||(!day.isBefore(today)&&(chosenDate.isBefore(today)||day.isBefore(chosenDate)))||(day.isBefore(today)&&chosenDate.isBefore(today)&&day.isAfter(chosenDate))){chosen=item;chosenDate=day;}}catch(Exception ignored){}}if(chosen==null)return "在手机添加\n一个重要日期";long days=ChronoUnit.DAYS.between(today,chosenDate);return chosen.optString("title")+"\n"+(days==0?"就是今天":days>0?"还有 "+days+" 天":"已过 "+(-days)+" 天");}
 static long focusRemaining(JSONObject cfg,long now){long end=cfg.optLong("focusEnd",0);return end>0?Math.max(0,end-now):Math.max(0,cfg.optLong("focusPaused",0));}
 static String focusState(JSONObject cfg,long now){return cfg.optLong("focusEnd",0)>now?"专注进行中":cfg.optLong("focusPaused",0)>0?"已暂停":cfg.optLong("focusEnd",0)>0?"本段专注已完成":"准备开始";}
 static JSONObject focus(JSONObject original,String operation,long now)throws Exception{JSONObject cfg=DeskModel.copy(original);if(operation.equals("start")){int minutes=cfg.optInt("focusMinutes",25);if(minutes<5||minutes>90)throw new Exception("专注时长5至90分钟");cfg.put("focusSession",UUID.randomUUID().toString()).put("focusEnd",now+minutes*60000L).put("focusPaused",0);}else if(operation.equals("pause")){long left=focusRemaining(cfg,now);if(cfg.optLong("focusEnd",0)<=now)throw new Exception("没有正在进行的专注");cfg.put("focusEnd",0).put("focusPaused",left);}else if(operation.equals("resume")){long left=cfg.optLong("focusPaused",0);if(left<=0)throw new Exception("没有暂停的专注");cfg.put("focusEnd",now+left).put("focusPaused",0);}else if(operation.equals("stop"))cfg.put("focusEnd",0).put("focusPaused",0).put("focusSession","");else throw new Exception("未知计时操作");return cfg;}
 static String outdoor(JSONObject weather,Instant now){if(weather==null)return "联网后更新天气";if(now.toEpochMilli()-weather.optLong("fetched",0)>3600000)return "天气已过期\n请更新天气";try{JSONObject h=weather.getJSONObject("hourly");JSONArray time=h.getJSONArray("time"),rain=h.getJSONArray("precipitation_probability"),feel=h.getJSONArray("apparent_temperature");double maximum=-1,apparent=Double.NaN;for(int i=0;i<time.length();i++){Instant at=LocalDateTime.parse(time.getString(i)).atZone(ZONE).toInstant();if(at.isBefore(now.minusSeconds(1800))||!at.isBefore(now.plusSeconds(10800)))continue;if(!rain.isNull(i))maximum=Math.max(maximum,rain.getDouble(i));if(Double.isNaN(apparent)&&!feel.isNull(i))apparent=feel.getDouble(i);}if(maximum<0)return "逐小时预报待更新";return "3小时降雨最高 "+Math.round(maximum)+"%\n"+(maximum>=60?"出门记得带伞":Double.isNaN(apparent)?"出门前再看天气":"体感 "+Math.round(apparent)+"℃");}catch(Exception e){return "逐小时预报待更新";}}
 static String lunar(Instant now){try{android.icu.util.ChineseCalendar cal=new android.icu.util.ChineseCalendar(android.icu.util.TimeZone.getTimeZone("Asia/Shanghai"));cal.setTimeInMillis(now.toEpochMilli());String[] months={"正","二","三","四","五","六","七","八","九","十","冬","腊"};int day=cal.get(android.icu.util.Calendar.DAY_OF_MONTH);String date=day<=10?"初"+new String[]{"一","二","三","四","五","六","七","八","九","十"}[day-1]:day<20?"十"+new String[]{"一","二","三","四","五","六","七","八","九"}[day-11]:day==20?"二十":day<30?"廿"+new String[]{"一","二","三","四","五","六","七","八","九"}[day-21]:"三十";return "农历 "+(cal.get(android.icu.util.ChineseCalendar.IS_LEAP_MONTH)==1?"闰":"")+months[cal.get(android.icu.util.Calendar.MONTH)]+"月"+date;}catch(Exception e){return "农历暂不可用";}}
 // Reuses this project's verified 2026 term dates. Other years are deliberately not guessed.
 static String term(Instant now){LocalDate date=now.atZone(ZONE).toLocalDate();if(date.getYear()!=2026)return "时令生活";String[] keys={"01-05","01-20","02-04","02-18","03-05","03-20","04-05","04-20","05-05","05-21","06-05","06-21","07-07","07-23","08-07","08-23","09-07","09-23","10-08","10-23","11-07","11-22","12-07","12-22"},names={"小寒","大寒","立春","雨水","惊蛰","春分","清明","谷雨","立夏","小满","芒种","夏至","小暑","大暑","立秋","处暑","白露","秋分","寒露","霜降","立冬","小雪","大雪","冬至"};String current=date.format(DateTimeFormatter.ofPattern("MM-dd"));for(int i=0;i<keys.length;i++)if(keys[i].compareTo(current)>=0)return (keys[i].equals(current)?"今日 · ":"下个节气 · ")+names[i]+" "+keys[i];return "岁末 · 静候新年";}
 static JSONObject adopt(JSONObject local,JSONObject state)throws Exception{JSONObject source=state.optJSONObject("phone_settings");if(!state.optString("layout_id").endsWith(".phone")||source==null)return DeskModel.copy(local);String layout=source.optString("layout","");if(!Arrays.asList("focus","agenda","minimal","overview","pomodoro","living","custom","calendar").contains(layout))return DeskModel.copy(local);JSONObject c=DeskModel.copy(local);for(String key:new String[]{"layout","ratio","scene","cardsVersion","card1","card2","weeklyGoal","note","deskStatus","statusNote","focusMinutes","focusEnd","focusPaused","focusSession","focusTask"})if(source.has(key))c.put(key,source.get(key));if(c.optInt("ratio",67)<40||c.optInt("ratio",67)>75||c.optInt("weeklyGoal",20)<1||c.optInt("weeklyGoal",20)>999||c.optInt("focusMinutes",25)<5||c.optInt("focusMinutes",25)>90||c.optLong("focusPaused",0)<0||c.optLong("focusPaused",0)>5400000||c.optLong("focusEnd",0)<0||c.optLong("focusEnd",0)>4102444800000L||c.optString("note").length()>100||c.optString("statusNote").length()>30||c.optString("deskStatus").length()>30)throw new Exception("设备卡片配置无效，保留本机设置");JSONArray dates=c.optJSONArray("dates");if(dates!=null){if(dates.length()>12)throw new Exception("设备日期配置过长");for(int i=0;i<dates.length();i++){JSONObject d=dates.getJSONObject(i);if(d.getString("title").length()>30)throw new Exception("设备日期名称过长");LocalDate.parse(d.getString("date"));}}return c;}
 static JSONObject scene(JSONObject original,String scene)throws Exception{JSONObject c=DeskModel.copy(original).put("cardsVersion",1);if(scene.equals("work"))c.put("scene","work").put("layout","overview").put("card1","plant").put("card2","countdown");else if(scene.equals("focus"))c.put("scene","focus").put("layout","pomodoro");else if(scene.equals("life"))c.put("scene","life").put("layout","calendar");else throw new Exception("不支持的场景");return c;}
}
